ALTER TABLE "note" ADD CONSTRAINT "note_body_sealed" CHECK (("note"."author" = 'server' and "note"."kind" = 'event' and "note"."body" ~ '^(?:Marked done[.]|Queued for a fresh run[.]|Closed[.]|Reopened[.]|Closed after [0-9]{1,9} days in Done[.]|Moved from (?:backlog|todo|running|waiting|needs-me|done) to (?:backlog|todo|running|waiting|needs-me|done)[.]|Priority (?:urgent|high|normal|low) → (?:urgent|high|normal|low)[.]|Start time cleared[.]|Start time set to [0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{3}Z[.]|Wait ended by you[.]|Your message reached the agent after its run ended\x3b resuming with it[.]|Taken back from [^\r\n]{1,128}[^\r\n]{0,128}: no sign of life for [0-9]{1,4} minutes[.]|Recorded before this board was migrated[.])$') or ("note"."author" <> 'server' and "note"."body" ~ '^abe1[.][A-Za-z0-9_-]{38,}$' and char_length("note"."body") <= 533376));